use callisto_model::{ApplyPermit, CommandRunner, CreatedTag, PublishPlan, TagReport, SCHEMA_VERSION};
use callisto_vcs::{GitAccess, GitDataSource, TagSignPolicy, VcsError};

use crate::error::GraphError;
use crate::resolver::DependencyResolver;
use crate::Workspace;

#[derive(Clone, Debug, Default)]
pub struct TagOptions {
    pub floating_major: bool,
}

/// Computes the floating-major tag name and existence check for `release`,
/// or `None` if this package's template can't produce one (no version could
/// be extracted/parsed, or the template renders no floating-major form).
/// Shared by both the preview and write branches of
/// [`create_tags_with_options`] so a future change to template rendering or
/// version-grammar resolution can't make the preview disagree with what
/// actually gets tagged.
fn plan_floating_major<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    release: &callisto_model::ReleaseEntry,
) -> Result<Option<(callisto_model::TagName, bool)>, GraphError> {
    let tmpl = ws.tags()?.template(&release.package);
    let Some(v_str) = tmpl.extract_version_str(release.tag_name.as_str()) else {
        return Ok(None);
    };
    let grammar = ws
        .graph
        .packages()
        .find(|p| p.id == release.package)
        .and_then(|p| p.version_grammar().ok())
        .unwrap_or(callisto_model::VersionGrammar::SemVer);
    let Ok(ver) = callisto_model::Version::parse(v_str, grammar) else {
        return Ok(None);
    };
    let Some(major_tag) = tmpl.render_floating_major(&ver) else {
        return Ok(None);
    };
    let already_existed = ws.tags()?.contains_tag(major_tag.as_str());
    Ok(Some((major_tag, already_existed)))
}

/// Resolves the sha a tag report should carry for `tag_str`: the tag's actual
/// target if it already exists, or `release.sha` if it doesn't yet exist.
/// Shared by the preview and write branches of [`create_tags_with_options`]
/// so a tag that already exists can't be reported with a different sha
/// depending on which branch resolved it -- mirrors [`plan_floating_major`]'s
/// role for the floating-major case.
fn resolve_existing_or_release_sha<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    git: &GitAccess<'_>,
    tag_str: &str,
    release: &callisto_model::ReleaseEntry,
) -> Result<(String, bool), GraphError> {
    let already_existed = ws.tags()?.contains_tag(tag_str);
    let sha = if already_existed {
        match git.resolve_commit(tag_str)? {
            Some(actual) => actual,
            None => {
                return Err(GraphError::Vcs(VcsError::RefNotFound {
                    ref_name: tag_str.to_string(),
                }))
            }
        }
    } else {
        release.sha.clone()
    };
    Ok((sha, already_existed))
}

pub fn create_tags<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    plan: &PublishPlan,
    permit: Option<&ApplyPermit>,
) -> Result<TagReport, GraphError> {
    create_tags_with_options(ws, plan, &TagOptions::default(), permit)
}

/// Creates one git tag per release in `plan`.
///
/// `permit` is the dry-run gate: `None` reports the tags that *would* be
/// created without touching a single ref, `Some` creates them. It replaces the
/// former `TagOptions::dry_run` bool so that the preview branch and the write
/// branch cannot disagree -- the write calls simply do not typecheck without a
/// permit in hand.
pub fn create_tags_with_options<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    plan: &PublishPlan,
    opts: &TagOptions,
    permit: Option<&ApplyPermit>,
) -> Result<TagReport, GraphError> {
    let mut tags = Vec::new();

    // `Workspace::git_access` never hard-fails on a missing gix discovery:
    // `wasm32` has no gix at all (excluded from that target's dependency
    // set), and even natively a failed discovery just means every op below
    // runs through the `CommandRunner` fallback instead. Its write
    // operations (`create_tag`/`create_floating_major`) additionally
    // guarantee a discovered repo's result is authoritative and never
    // masked by a shell retry -- see `GitAccess`'s doc comment. Sharing the
    // workspace-scoped instance (rather than a fresh `GitAccess::discover`)
    // means this command doesn't pay for a second discovery when `ws.tags()`
    // below also needs one.
    let git = ws.git_access();

    for release in &plan.releases {
        let tag_str = release.tag_name.as_str();

        let Some(permit) = permit else {
            if opts.floating_major {
                if let Some((major_tag, already_existed)) = plan_floating_major(ws, release)? {
                    tags.push(CreatedTag {
                        package: release.package.clone(),
                        tag_name: major_tag,
                        sha: release.sha.clone(),
                        already_existed,
                        is_floating_major: true,
                    });
                }
            }

            let (sha, already_existed) =
                resolve_existing_or_release_sha(ws, git, tag_str, release)?;

            tags.push(CreatedTag {
                package: release.package.clone(),
                tag_name: release.tag_name.clone(),
                sha,
                already_existed,
                is_floating_major: false,
            });
            continue;
        };

        let (sha, already_existed) = resolve_existing_or_release_sha(ws, git, tag_str, release)?;

        if !already_existed {
            let msg = format!("Release {}", tag_str);
            git.create_tag(
                tag_str,
                &release.sha,
                Some(&msg),
                TagSignPolicy::RespectRepoConfig,
                permit,
            )?;
        }

        if opts.floating_major {
            if let Some((major_tag, already_existed)) = plan_floating_major(ws, release)? {
                git.create_floating_major(major_tag.as_str(), &release.sha, permit)?;
                tags.push(CreatedTag {
                    package: release.package.clone(),
                    tag_name: major_tag,
                    sha: release.sha.clone(),
                    already_existed,
                    is_floating_major: true,
                });
            }
        }

        tags.push(CreatedTag {
            package: release.package.clone(),
            tag_name: release.tag_name.clone(),
            sha,
            is_floating_major: false,
            already_existed,
        });
    }

    Ok(TagReport {
        schema_version: SCHEMA_VERSION,
        tags,
        diagnostics: Vec::new(),
    })
}

